'use strict';
const SERVICES_UI6={bind,help};
function serviceAllDialog6(){show(`<h2>Servis celé firmy</h2>${field('Rozsah opravy',`<select id="serviceAllScope6"><option value="all">Kavárny, výrobny a vozy</option><option value="cafes">Jen vlastní kavárny</option><option value="factories">Jen výrobny a vozy</option></select>`)}<div id="serviceAllQuote6"></div><div class="actions"><button class="primary" id="serviceAllConfirm6">Zaplatit a opravit vše v rozsahu</button><button class="soft" id="serviceAllCancel6">Zrušit</button><button class="quiet" id="serviceAllHistory6">Historie servisu</button></div>`);let quote;const refresh=()=>{quote=serviceAllQuote6(el('serviceAllScope6').value);el('serviceAllQuote6').innerHTML=rows([['Opravy pod 100 % stavu',quote.items.length],['Celková platba',money(quote.total)],['Zůstatek po servisu',money(quote.cash-quote.total)]])+`<p class="sub">Vlastní zařízení se obnoví na 100 %. Servis smluvní pražírny zajišťuje dodavatel bez doplatku. Oprava vybavení současně obnoví provozní stav kavárny; samostatná kontrola se pak neplatí podruhé. Franšízové vybavení spravuje partner.</p>${quote.items.length?'<details><summary>Seznam a jednotlivé ceny</summary>'+rows(quote.items.map(x=>[esc(x.name)+' · '+number(x.before,1)+' % → 100 %',money(x.cost)]))+'</details>':empty('V tomto rozsahu je vše v plném technickém stavu.')}<p class="sub">${quote.cash-quote.total<weeklyFixed()*3?'Po servisu by zůstala rezerva menší než tři týdny fixních nákladů.':'Platba se projeví v nejbližším týdenním výsledku.'}</p>`;el('serviceAllConfirm6').disabled=state.over||!quote.items.length||quote.cash<quote.total;};el('serviceAllScope6').onchange=refresh;el('serviceAllCancel6').onclick=()=>el('modal').close();el('serviceAllHistory6').onclick=serviceHistoryDialog6;el('serviceAllConfirm6').onclick=()=>act(()=>{const receipt=serviceAll6(quote.scope,quote);persist();render();show(`<h2>Servis dokončen</h2>${rows([['Opraveno',receipt.items.length+' zařízení / kontrol'],['Zaplaceno',money(receipt.total)],['Technický stav','100 %']])}<button class="soft" id="serviceAllReceipt6">Otevřít účtenku a historii</button>`);el('serviceAllReceipt6').onclick=serviceHistoryDialog6;});refresh();}
function serviceHistoryDialog6(){show(`<h2>Historie společného servisu</h2>${state.services6.history.slice().reverse().map(h=>`<details><summary>T${h.week} · ${h.items.length} oprav · ${money(h.total)}</summary>${rows(h.items.map(x=>[esc(x.name)+' · '+number(x.before,1)+' % → 100 %',money(x.cost)]))}</details>`).join('')||empty('Zatím nebyl proveden společný servis.')}<button class="soft" id="serviceAllBack6">Nový servis</button>`);el('serviceAllBack6').onclick=serviceAllDialog6;}
bind=function(){SERVICES_UI6.bind();el('serviceAll6').onclick=serviceAllDialog6;};
help=function(){SERVICES_UI6.help();const p=document.createElement('p');p.textContent='Tlačítko Servis všeho v horní liště připraví jednu nabídku na opravy vlastních kaváren, pražíren, pekáren a rozvozových vozů. Před platbou vybereš rozsah, uvidíš ceny a zůstatek. Zařízení ve 100% stavu se neopravují znovu. Bez peněz na celý zvolený rozsah se neprovede žádná oprava; účtenka zůstane uložená v historii.';el('modalContent').append(p);};el('help').onclick=help;render();
